def build_using_sentence(account: Optional[str], key: Optional[str], db:
    Optional[str]) ->List[Dict[str, Any]]:
    result = []

    if account:
        result.append({'style': True, 'value': f'using account {account}'})
    elif key:
        result.append({'style': True, 'value': 'using API key'})

    if db:
        result.append({'style': True, 'value': f'with local database {db}'})

    if result:
        result.insert(0, {'style': False, 'value': 'Using '})
        result.append({'style': False, 'value': '.'})
    else:
        result.append({'style': False, 'value': 'Using default settings.'})

    return result
